    bytes_delivered: offset,
    bytes_produced: offset + discarded_bytes,
    partial_reason: entry_partial_reason,
    ratio: if entry_compressed_in > 0 {
        offset as f32 / entry_compressed_in as f32
    } else {
        0.0
    },
};
sink.on_entry_end(summary)?;
```

