Step 3: Implement read_decompressed for RawDeflate:

Follow the pattern from pack_inflate.rs:456-541 (inflate_limited_with):

```rust
fn read_decompressed(&mut self, out: &mut [u8]) -> io::Result<usize> {
    match self {
        Self::Stored(r) => r.read(out),
        Self::RawDeflate { de, source, read_buf, read_pos, read_len, finished } => {
            if *finished { return Ok(0); }
            let mut out_pos = 0;
            while out_pos < out.len() {
                if *read_pos >= *read_len {
                    let n = source.read(&mut read_buf[..])?;
                    if n == 0 && out_pos == 0 { return Ok(0); }
                    if n == 0 { break; }
                    *read_pos = 0;
                    *read_len = n;
                }
                let before_in = de.total_in();
                let before_out = de.total_out();
                let status = de.decompress(
                    &read_buf[*read_pos..*read_len],
                    &mut out[out_pos..],
                    flate2::FlushDecompress::None,
                ).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
                let consumed = (de.total_in() - before_in) as usize;
                let produced = (de.total_out() - before_out) as usize;
                *read_pos += consumed;
                out_pos += produced;
                if matches!(status, flate2::Status::StreamEnd) {
                    *finished = true;
                    break;
                }
                if consumed == 0 && produced == 0 { break; }
            }
            Ok(out_pos)
        }
    }
}
```

